// Package netsec implements a server-owned, number-matching push challenge
// state machine for Go authentication hosts.
//
// The package deliberately keeps all security-sensitive decisions on the
// server: challenge identifiers are generated by the host, display codes are
// derived with HMAC-SHA256, device responses are Ed25519-signed over the full
// challenge binding, and every state transition is serialized under one lock.
//
// A typical flow is:
//
//	srv, _ := netsec.NewServer(netsec.Config{ServiceKey: key})
//	_ = srv.RegisterDevice(deviceID, accountID, devicePublicKey)
//	tx, _ := srv.BeginLogin(accountID, browserSessionID)
//	ch, _ := srv.CreateChallenge(netsec.ChallengeRequest{...}, pushSender)
//	// The device signs ch.SigningMessage(DecisionApprove, ch.DisplayCode).
//	_, _ = srv.Respond(response)
//	session, _ := srv.ConsumeApproval(tx.ID, ch.ID)
//
// See Auditor for a deterministic two-browser interleaving search that checks
// whether an attacker browser can obtain a session without the user approving
// the attacker's request digest.
package netsec
